fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of rows in the input matrix
    let rows = x.len();
    // Number of columns in the input (assumes at least one row)
    let cols = x[0].len();

    // Initialize the transposed matrix with `cols` rows and `rows` columns,
    // filling with 0.0 as a placeholder.
    let mut result: Vec<Vec<f32>> = vec![vec![0.0; rows]; cols];

    // Fill in the transposed values: result[c][r] = x[r][c].
    for r in 0..rows {
        for c in 0..cols {
            result[c][r] = x[r][c];
        }
    }

    result
}